{"command": "cd /tmp && kubectl -n default get deployment app -o json > now.json && python3 - <<'EOF'
import json
a=json.load(open('app.json'))['spec']['template']['spec']
b=json.load(open('now.json'))['spec']['template']['spec']
def flat(d,p=''):
    out={}
    if isinstance(d,dict):
        for k,v in d.items(): out.update(flat(v,f"{p}.{k}" if p else k))
    elif isinstance(d,list):
        for i,v in enumerate(d): out.update(flat(v,f"{p}[{i}]"))
    else: out[p]=d
    return out
fa,fb=flat(a),flat(b)
for k in sorted(set(fa)|set(fb)):
    if fa.get(k)!=fb.get(k): print(f"{k}: {fa.get(k)!r} -> {fb.get(k)!r}")
EOF"}

